        )
    )
    result = pd.Series(arr).str.partition("b")
    expected = pd.DataFrame(
        [["a", "b", "cba"], ["a", "", ""], [None, None, None]],
        dtype=ArrowDtype(pa.string()),
        columns=pd.RangeIndex(3),
    )
    tm.assert_frame_equal(result, expected, check_column_type=True)

